+package semtypes
+
+import "encoding/binary"
+
+// cellAtomShape returns an encoding of atomicType that is equal for two cell
+// atomic types only if they have identical representations. It returns "" when
+// the cell's type has a proper subtype that is not a BDD, since only BDDs have
+// canonical keys that identify their structure.
+func cellAtomShape(atomicType *cellAtomicType) string {
+	var arr [32]byte
+	buf := binary.AppendUvarint(arr[:0], uint64(atomicType.Mut))
+	buf = binary.AppendUvarint(buf, uint64(atomicType.Ty.all()))
+	buf = binary.AppendUvarint(buf, uint64(atomicType.Ty.some()))
+	for _, data := range atomicType.Ty.subtypeDataList() {
+		b, ok := data.(bdd)
+		if !ok {
+			return ""
+		}
+		buf = binary.AppendUvarint(buf, uint64(b.canonicalKey()))
+	}
+	return string(buf)
+}
